-- ABWEHR CLASSIC PRIME: final distinct cards, hidden pending review.
begin;
create temporary table t(slug text primary key,name text,url text,photos text[]) on commit drop;
select slug,'entrance','Abwehr','Classic Prime',name,'Сталь, МДФ-накладки та заводські покриття','Сучасний','Заводські декори','Ціна за запитом',name || ' — вхідні двері для квартири серії Classic Prime. Три контури ущільнення та утеплена конструкція допомагають зберігати комфорт у приміщенні; точну комплектацію, декори й ціну уточнюйте у менеджера.',jsonb_build_array('Фабрика Abwehr','Колекція Classic Prime','3 контури ущільнення'),photos[1],99999,false from t on conflict(slug) do update set name=excluded.name,description=excluded.description,features=excluded.features,image_path=excluded.image_path;
commit;
select count(*) as моделей,count(*) filter(where is_available) as опубліковано,(select count(*) from public.product_media m where m.product_slug in('abwehr-classic-louna-official','abwehr-classic-nika-official','abwehr-classic-iris-official','abwehr-classic-armana-official') and m.kind='gallery') as фото_в_галереях,count(*) filter(where image_path is not null) as моделей_з_фото from public.products where slug in('abwehr-classic-louna-official','abwehr-classic-nika-official','abwehr-classic-iris-official','abwehr-classic-armana-official');
