insert into public.products(slug,category,brand,collection,name,material,style,color,price,description,features,image_path,sort_order,is_available)
insert into public.product_specs(product_slug,label,value,sort_order,is_active) select slug,label,value,sort_order,true from t cross join lateral(values('Тип конструкції','Вхідні двері для квартири',10),('Колекція','Classic Prime',20),('Призначення','Для квартири',30),('Контури ущільнення','3 контури',40))s(label,value,sort_order) on conflict(product_slug,label) do update set value=excluded.value,sort_order=excluded.sort_order,is_active=true;
insert into public.product_sources(product_slug,source_name,source_url,source_product_name,verification_status,verified_at,notes) select slug,'ABWEHR',url,name || ' · Classic Prime','verified',now(),'Офіційна картка виробника: окрема модель та фотогалерея.' from t where not exists(select 1 from public.product_sources x where x.product_slug=t.slug and x.source_url=t.url);
insert into public.product_media(product_slug,kind,label,image_path,sort_order) select slug,'main','Головне фото',photos[1],0 from t where not exists(select 1 from public.product_media x where x.product_slug=t.slug and x.kind='main' and x.image_path=t.photos[1]);
insert into public.product_media(product_slug,kind,label,image_path,sort_order) select t.slug,'gallery','Офіційне фото '||p.ordinality,p.path,p.ordinality from t cross join lateral unnest(t.photos) with ordinality p(path,ordinality) where not exists(select 1 from public.product_media x where x.product_slug=t.slug and x.kind='gallery' and x.image_path=p.path);
